// Chase camera for the local glider: sits behind and above, lags on turns,
// widens its field of view with speed, shakes on collisions and shows speed
// streaks in wind currents. P toggles photo mode: the HUD hides and the camera
// slowly orbits the glider. Before take-off it drifts around the start area.
function pg(ctx) { return ctx.engine.procgen || null; }

defineScript({
  name: 'ChaseCamera',
  description: 'Speed-aware chase camera with photo mode.',
  props: {
    distance: { type: 'number', default: 7.5, min: 2, max: 40 },
    height: { type: 'number', default: 2.4, min: 0, max: 20 },
    lookAhead: { type: 'number', default: 14, min: 0, max: 60 },
    smoothing: { type: 'number', default: 6, min: 0.5, max: 30 },
    fov: { type: 'number', default: 62, min: 30, max: 120 },
    fovPerSpeed: { type: 'number', default: 0.32, min: 0, max: 2 },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.photo = false; s.orbit = 0; s.shake = 0; s.prev = null; s.speed = 0; s.streaks = [];
    s.look = new ctx.math.Vec3(); s.tmp = new ctx.math.Vec3(); s.fwd = new ctx.math.Vec3(); s.up = new ctx.math.Vec3();
    s.streakRng = new ctx.math.Random(4242);
    s.cinema = 0;
    s.started = ctx.net.online && !ctx.net.isHost; // guests join a flight already in progress
  },
  ensureStreaks(ctx) {
    const s = ctx.state, P = pg(ctx);
    if (s.streaks.length || !P || !P.world) return;
    const key = `${P.world.seed}:wind-streak`;
    const desc = P.registered(key) || P.registerGenerated(key, P.world.library('wind-streak'));
    for (let i = 0; i < 14; i++) {
      const e = ctx.world.createEntity('Speed Streak');
      const t = ctx.getOn(e, 'Transform');
      const c = ctx.world.createEntity('streak');
      ctx.world.setParent(c, e);
      const mr = ctx.world.addComponentByType(c, 'MeshRenderer', { mesh: desc.groups[0].mesh });
      P.applyMaterial(mr, desc.groups[0]);
      mr.opacity = 0.25;
      mr.visible = false;
      s.streaks.push({ e, t, mr, life: 0, off: { x: 0, y: 0, z: 0 } });
    }
  },
  onDestroy(ctx) { for (const st of ctx.state.streaks || []) if (ctx.world.isAlive(st.e)) ctx.destroy(st.e); },
  onMessage(ctx, name, data) {
    const s = ctx.state;
    if (name === 'collision' && (data.peer === ctx.net.localId || data.peer === 'local')) {
      const r = ctx.engine.renderer;
      if (r && typeof r.setCameraShake === 'function') r.setCameraShake(0.15 + data.strength * 0.35, 4);
      else ctx.state.shake = Math.max(ctx.state.shake, 0.4 + data.strength * 0.8);
    }
    if (name === 'shell:fly' || name === 'shell:race' || name === 'takeControl') s.started = true;
    if (name === 'worldSeed') { for (const st of ctx.state.streaks) if (ctx.world.isAlive(st.e)) ctx.destroy(st.e); ctx.state.streaks = []; }
  },
  localGlider(ctx) {
    for (const e of ctx.findAll('glider')) {
      const pi = ctx.getOn(e, 'PlayerInput');
      if (pi && (pi.owner === 'local' || pi.owner === ctx.net.localId)) return e;
    }
    return undefined;
  },
  onLateUpdate(ctx, dt) {
    const s = ctx.state, M = ctx.math, t = ctx.transform;
    const cam = ctx.get('Camera3D');
    if (ctx.input.keyboard.pressed('KeyP') || ctx.input.pressed('photo')) { s.photo = !s.photo; ctx.send('photoMode', { on: s.photo }); }
    const glider = this.localGlider(ctx);
    if (glider === undefined || !s.started) { this.cinematic(ctx, dt); return; }
    const gt = ctx.getOn(glider, 'Transform');
    const gp = gt.position;
    if (s.prev && dt > 0) s.speed = M.damp(s.speed, Math.min(200, Math.hypot(gp.x - s.prev.x, gp.y - s.prev.y, gp.z - s.prev.z) / dt), 5, dt);
    s.prev = { x: gp.x, y: gp.y, z: gp.z };
    gt.updateWorldMatrix();
    gt.forward(s.fwd);
    s.shake = Math.max(0, s.shake - dt * 1.8);
    if (s.photo) {
      s.orbit += dt * 0.22;
      const r = 8 + Math.sin(s.orbit * 0.5) * 2, h = 2 + Math.sin(s.orbit * 0.31) * 1.5;
      t.setPosition(gp.x + Math.cos(s.orbit) * r, gp.y + h, gp.z + Math.sin(s.orbit) * r);
      t.updateWorldMatrix();
      t.lookAt(s.look.set(gp.x, gp.y, gp.z));
      if (cam) cam.fov = M.damp(cam.fov, 45, 2, dt);
      this.streaks(ctx, dt, gp, 0);
      return;
    }
    const dist = ctx.props.distance + s.speed * 0.05;
    // Follow the heading in the horizontal plane so pitch does not swing the camera under the glider.
    const fx = s.fwd.x, fz = s.fwd.z, fl = Math.hypot(fx, fz) || 1;
    const hx = fx / fl, hz = fz / fl;
    const tx = gp.x - hx * dist, ty = gp.y + ctx.props.height - s.fwd.y * 2.5, tz = gp.z - hz * dist;
    const k = ctx.props.smoothing;
    const nx = M.damp(t.x, tx, k, dt), ny = M.damp(t.y, ty, k * 0.8, dt), nz = M.damp(t.z, tz, k, dt);
    const sh = s.shake * s.shake * 0.5;
    t.setPosition(nx + (Math.random() - 0.5) * sh, ny + (Math.random() - 0.5) * sh, nz + (Math.random() - 0.5) * sh);
    t.updateWorldMatrix();
    s.look.set(gp.x + s.fwd.x * ctx.props.lookAhead, gp.y + s.fwd.y * ctx.props.lookAhead * 0.6 + 0.6, gp.z + s.fwd.z * ctx.props.lookAhead);
    t.lookAt(s.look);
    if (cam) cam.fov = M.damp(cam.fov, ctx.props.fov + s.speed * ctx.props.fovPerSpeed, 3, dt);
    const P = pg(ctx);
    let wind = 0;
    if (P && P.world) { P.world.windAt(gp, s.tmp); wind = s.tmp.length(); }
    this.streaks(ctx, dt, gp, Math.max(0, (s.speed - 34) / 30) + Math.min(1, wind / 6));
  },
  /** Before any glider exists (start screen): a slow drift around the start of the flow path. */
  cinematic(ctx, dt) {
    const s = ctx.state, P = pg(ctx), t = ctx.transform;
    s.cinema += dt;
    const W = P && P.world;
    const sp = W ? W.spawn(0).position : { x: 0, y: 50, z: 0 };
    const a = s.cinema * 0.06 + 2.2;
    t.setPosition(sp.x + Math.cos(a) * 95, sp.y + 22 + Math.sin(a * 0.7) * 5, sp.z + Math.sin(a) * 95);
    t.updateWorldMatrix();
    t.lookAt(s.look.set(sp.x, sp.y - 10, sp.z));
    const cam = ctx.get('Camera3D');
    if (cam) cam.fov = 58;
  },
  /** Speed streaks: thin translucent lines rushing past the camera, more with speed and inside wind. */
  streaks(ctx, dt, gp, intensity) {
    const s = ctx.state;
    this.ensureStreaks(ctx);
    if (!s.streaks.length) return;
    const t = ctx.transform;
    t.forward(s.fwd);
    const speed = Math.max(20, s.speed);
    for (const st of s.streaks) {
      if (st.life <= 0) {
        if (intensity > 0.05 && s.streakRng.chance(Math.min(0.5, intensity * 0.35))) {
          st.life = 1;
          st.off.x = s.streakRng.range(-6, 6); st.off.y = s.streakRng.range(-3, 4); st.off.z = s.streakRng.range(10, 40);
          st.mr.visible = true;
        } else { st.mr.visible = false; continue; }
      }
      st.life -= dt * speed / 40;
      st.off.z -= speed * dt * 1.4;
      if (st.off.z < -6) st.life = 0;
      // Position relative to the glider frame: ahead along the camera forward, offset sideways.
      const rx = -s.fwd.z, rz = s.fwd.x;
      st.t.setPosition(gp.x + s.fwd.x * st.off.z + rx * st.off.x, gp.y + st.off.y + s.fwd.y * st.off.z, gp.z + s.fwd.z * st.off.z + rz * st.off.x);
      st.t.setScale(1, 1, 1 + speed / 25);
      st.t.updateWorldMatrix();
      st.t.lookAt(s.look.set(st.t.x + s.fwd.x, st.t.y + s.fwd.y, st.t.z + s.fwd.z));
      st.mr.opacity = 0.08 + Math.min(0.35, intensity * 0.3) * Math.sin(st.life * Math.PI);
    }
  },
});

// A small flock of birds circling an island: classic boids (separation,
// alignment, cohesion) pulled toward an orbit around the anchor, with a
// scatter impulse when a glider passes close. Wing flap = swapping between two
// generated poses.
function pg(ctx) { return ctx.engine.procgen || null; }

defineScript({
  name: 'Flock',
  description: 'Boids circling an island; scatter when a glider passes.',
  props: {
    count: { type: 'integer', default: 7, min: 1, max: 30 },
    radius: { type: 'number', default: 18, min: 3, max: 100 },
    speed: { type: 'number', default: 9, min: 1, max: 40 },
    meshPrefix: { type: 'string', default: '' },
  },
  onStart(ctx) {
    const s = ctx.state, P = pg(ctx);
    s.birds = [];
    if (!P || !P.world) return;
    const W = P.world;
    const poses = ['up', 'down'].map((pose) => P.registered(`${ctx.props.meshPrefix}bird-${pose}`) || P.registerGenerated(`${ctx.props.meshPrefix}bird-${pose}`, W.library(`bird-${pose}`)));
    const c = ctx.transform.position;
    const rng = new ctx.math.Random((Math.abs(c.x * 13 + c.z * 7) | 0) + 1);
    for (let i = 0; i < ctx.props.count; i++) {
      const a = rng.range(0, Math.PI * 2), r = ctx.props.radius * rng.range(0.6, 1);
      const e = ctx.world.createEntity('Bird');
      const t = ctx.getOn(e, 'Transform');
      t.setPosition(c.x + Math.cos(a) * r, c.y + rng.range(-3, 3), c.z + Math.sin(a) * r);
      t.setScale(0.9, 0.9, 0.9);
      const parts = [];
      for (const g of poses[0].groups) {
        const ce = ctx.world.createEntity(g.name);
        ctx.world.setParent(ce, e);
        const mr = ctx.world.addComponentByType(ce, 'MeshRenderer', { mesh: g.mesh });
        P.applyMaterial(mr, g);
        parts.push({ mr, name: g.name });
      }
      s.birds.push({ e, t, parts, v: { x: -Math.sin(a) * ctx.props.speed, y: 0, z: Math.cos(a) * ctx.props.speed }, flap: rng.range(0, 1), flapRate: rng.range(5, 8), pose: 0, scare: 0 });
    }
    s.poses = poses;
    s.look = new ctx.math.Vec3();
  },
  onDestroy(ctx) { for (const b of ctx.state.birds || []) if (ctx.world.isAlive(b.e)) ctx.destroy(b.e); },
  onUpdate(ctx, dt) {
    const s = ctx.state;
    if (!s.birds || !s.birds.length) return;
    const dtc = Math.min(dt, 0.05);
    const c = ctx.transform.position, R = ctx.props.radius, V = ctx.props.speed;
    // Nearest glider (any peer) for the scatter reaction.
    let threat = null, td = 1e9;
    for (const g of ctx.findAll('glider')) {
      const gt = ctx.getOn(g, 'Transform');
      const d = Math.hypot(gt.x - c.x, gt.y - c.y, gt.z - c.z);
      if (d < td) { td = d; threat = gt; }
    }
    const birds = s.birds;
    for (let i = 0; i < birds.length; i++) {
      const b = birds[i], p = b.t.position;
      let ax = 0, ay = 0, az = 0;
      let cx = 0, cy = 0, cz = 0, vx = 0, vy = 0, vz = 0, n = 0;
      for (let j = 0; j < birds.length; j++) {
        if (i === j) continue;
        const o = birds[j].t.position;
        const dx = p.x - o.x, dy = p.y - o.y, dz = p.z - o.z;
        const d2 = dx * dx + dy * dy + dz * dz;
        if (d2 < 9) { const k = 2.5 / Math.max(0.2, d2); ax += dx * k; ay += dy * k; az += dz * k; }
        if (d2 < 400) { cx += o.x; cy += o.y; cz += o.z; vx += birds[j].v.x; vy += birds[j].v.y; vz += birds[j].v.z; n++; }
      }
      if (n) {
        ax += ((cx / n) - p.x) * 0.25; ay += ((cy / n) - p.y) * 0.25; az += ((cz / n) - p.z) * 0.25;
        ax += ((vx / n) - b.v.x) * 0.6; ay += ((vy / n) - b.v.y) * 0.6; az += ((vz / n) - b.v.z) * 0.6;
      }
      // Orbit the anchor: pull toward the ring of radius R and along its tangent.
      const rx = p.x - c.x, rz = p.z - c.z, rl = Math.hypot(rx, rz) || 1;
      const ring = (R - rl) * 0.9;
      ax += (rx / rl) * ring - (rz / rl) * V * 0.5; az += (rz / rl) * ring + (rx / rl) * V * 0.5;
      ay += (c.y + Math.sin(ctx.time.elapsed * 0.3 + i) * 3 - p.y) * 0.6;
      if (threat) {
        const dx = p.x - threat.x, dy = p.y - threat.y, dz = p.z - threat.z;
        const d = Math.hypot(dx, dy, dz);
        if (d < 14) { const k = (14 - d) * 6 / Math.max(1, d); ax += dx * k; ay += dy * k + 8; az += dz * k; b.scare = 1.5; }
      }
      b.scare = Math.max(0, b.scare - dtc);
      b.v.x += ax * dtc; b.v.y += ay * dtc; b.v.z += az * dtc;
      const sp = Math.hypot(b.v.x, b.v.y, b.v.z) || 1;
      const target = V * (1 + b.scare * 0.8);
      const k = target / sp;
      b.v.x *= k; b.v.y *= k; b.v.z *= k;
      b.t.position.x += b.v.x * dtc; b.t.position.y += b.v.y * dtc; b.t.position.z += b.v.z * dtc;
      b.t.markDirty();
      b.t.updateWorldMatrix();
      b.t.lookAt(s.look.set(p.x + b.v.x, p.y + b.v.y * 0.5, p.z + b.v.z));
      b.flap += dtc * b.flapRate * (1 + b.scare);
      const pose = Math.floor(b.flap) % 2;
      if (pose !== b.pose) {
        b.pose = pose;
        for (const part of b.parts) { const g = s.poses[pose].groups.find((x) => x.name === part.name); if (g) part.mr.mesh = g.mesh; }
      }
    }
  },
});

// Host-side director: one Glider per player (spawned through the sync so
// everyone sees everyone), free-roam and race modes, countdown/standings/best
// times, the world seed shared through the room, and host migration
// (onHostChanged) so a guest can take over.
function hud(ctx) { return ctx.engine.canvas ? ctx.engine.hud : null; }
function pg(ctx) { return ctx.engine.procgen || null; }

defineScript({
  name: 'GameManager',
  description: 'Spawns gliders per player, runs races, shares the seed.',
  props: {
    seed: { type: 'string', default: 'amber-lagoon-42', label: 'World seed (fallback)' },
    countdown: { type: 'integer', default: 3, min: 0, max: 10 },
    raceTimeout: { type: 'number', default: 45, min: 5, max: 600, label: 'Seconds after the first finisher' },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.players = {}; s.count = 0; s.unsub = [];
    s.race = { phase: 'idle', startAt: 0, countdown: null, results: {} };
    s.mode = 'free';
    const W = this.world(ctx);
    s.seed = W ? W.seed : ctx.props.seed;
    if (ctx.net.isHost) this.becomeHost(ctx);
    this.drawStandings(ctx);
  },
  world(ctx) {
    const P = pg(ctx);
    if (!P) return null;
    if (!P.world) P.world = P.createWorld(P.env.param('seed') || (P.env.param('daily') ? P.seeds.dailySeed() : ctx.props.seed));
    return P.world;
  },
  onHostChanged(ctx, isHost) { if (isHost) this.becomeHost(ctx); },
  becomeHost(ctx) {
    const s = ctx.state;
    if (s.serving) return;
    s.serving = true;
    const sync = ctx.net.hub.sync;
    this.adoptPlayers(ctx);
    this.addPlayer(ctx, ctx.net.localId);
    if (sync) {
      for (const p of sync.players()) this.addPlayer(ctx, p.peerId);
      s.unsub.push(sync.on('playerJoined', ({ peerId }) => { this.addPlayer(ctx, peerId); this.resendHud(ctx); }));
      s.unsub.push(sync.on('playerLeft', ({ peerId }) => this.removePlayer(ctx, peerId)));
    }
    if (s.race.phase === 'running' && s.raceFirstFinish) ctx.timer(ctx.props.raceTimeout, () => this.endRace(ctx));
    this.resendHud(ctx);
  },
  /** New host: gliders the previous host spawned become our players; progress comes from the last HUD RPC. */
  adoptPlayers(ctx) {
    const s = ctx.state;
    const known = s.players;
    s.players = {};
    for (const e of ctx.world.with('NetworkIdentity')) {
      const ni = ctx.getOn(e, 'NetworkIdentity');
      if (ni.prefab !== 'Glider') continue;
      const props = ctx.getOn(e, 'Script').props;
      const k = known[ni.ownerId] || {};
      const index = k.index !== undefined ? k.index : props.livery || 0;
      s.players[ni.ownerId] = { entity: e, index, label: props.label || `P${index + 1}`, gates: k.gates || 0, time: k.time || 0, finished: k.finished || 0, flying: true };
      s.count = Math.max(s.count, index + 1);
    }
  },
  onDestroy(ctx) {
    for (const off of ctx.state.unsub) off();
    const h = hud(ctx);
    if (h) for (const id of ['countdown', 'standings', 'race-result']) h.remove(id);
  },
  addPlayer(ctx, peerId) {
    const s = ctx.state;
    if (s.players[peerId]) return;
    const W = this.world(ctx);
    const index = s.count++;
    const spawn = W ? W.spawn(index) : { position: { x: index * 6, y: 50, z: 0 }, yaw: 0 };
    const entity = ctx.net.spawn('Glider', { ownerId: peerId, position: spawn.position });
    const pi = ctx.getOn(entity, 'PlayerInput');
    if (pi) pi.owner = peerId;
    const ni = ctx.getOn(entity, 'NetworkIdentity');
    if (ni) ni.ownerId = peerId;
    const name = ctx.getOn(entity, 'Name');
    if (name) name.name = `Glider ${peerId}`;
    const script = ctx.getOn(entity, 'Script');
    script.props.livery = index % 6;
    script.props.label = `P${index + 1}`;
    script.props.heading = spawn.yaw;
    s.players[peerId] = { entity, index, label: `P${index + 1}`, gates: 0, time: 0, finished: 0, flying: false };
    if (s.race.phase === 'running') ctx.sendTo(entity, 'raceState', { phase: 'running', startAt: s.race.startAt });
  },
  removePlayer(ctx, peerId) {
    const p = ctx.state.players[peerId];
    if (!p) return;
    if (p.entity !== undefined && ctx.world.isAlive(p.entity)) {
      const sync = ctx.net.hub.sync;
      if (sync) sync.despawn(p.entity); else ctx.destroy(p.entity);
    }
    delete ctx.state.players[peerId];
    this.drawStandings(ctx);
  },
  localGlider(ctx) {
    for (const e of ctx.findAll('glider')) {
      const pi = ctx.getOn(e, 'PlayerInput');
      if (pi && (pi.owner === 'local' || pi.owner === ctx.net.localId)) return e;
    }
    return undefined;
  },

  // ----------------------------------------------------------- messages
  onMessage(ctx, name, data) {
    const s = ctx.state;
    if (name === 'shell:fly') {
      s.mode = 'free';
      if (ctx.net.isHost) this.takeOff(ctx, ctx.net.localId); else ctx.net.rpc('fly', [], 'host');
    } else if (name === 'shell:race') {
      if (ctx.net.isHost) { this.takeOff(ctx, ctx.net.localId); this.startRace(ctx); }
      else { ctx.net.rpc('fly', [], 'host'); ctx.net.rpc('requestRace', [], 'host'); }
    } else if (name === 'shell:seed') {
      if (!ctx.net.isHost) return;
      const P = pg(ctx);
      if (!P) return;
      const seed = P.seeds.normalizeSeed(data.seed);
      if (seed === s.seed) return;
      s.seed = seed;
      ctx.send('worldSeed', { seed });
      P.env.setParam('seed', seed);
    } else if (name === 'worldSeed') {
      // The streamer rebuilt the world: put every glider back on the new start line.
      const W = this.world(ctx);
      s.seed = W ? W.seed : data.seed;
      if (ctx.net.isHost) {
        for (const [peer, p] of Object.entries(s.players)) if (p.entity !== undefined && ctx.world.isAlive(p.entity) && W) ctx.sendTo(p.entity, 'resetTo', { position: W.spawn(p.index).position, yaw: W.spawn(p.index).yaw, peer });
        this.resetRace(ctx);
        this.resendHud(ctx);
      }
    } else if (!ctx.net.isHost) {
      return;
    } else if (name === 'gatePassed') {
      const p = s.players[data.peer];
      if (!p || s.race.phase !== 'running') return;
      p.gates = data.index + 1; p.time = data.time;
      ctx.send('nextGate', { index: p.gates, peer: data.peer });
      this.drawStandings(ctx);
    } else if (name === 'raceFinished') {
      const p = s.players[data.peer];
      if (!p || s.race.phase !== 'running' || p.finished) return;
      p.finished = data.time;
      s.race.results[data.peer] = data.time;
      const P = pg(ctx);
      const prev = P ? Number(P.env.storageGet(`driftwind.best.${s.seed}`) || 0) : 0;
      const best = data.peer === ctx.net.localId ? (!prev || data.time < prev) : false;
      ctx.send('raceResult', { peer: data.peer, time: data.time, best });
      if (!s.raceFirstFinish) { s.raceFirstFinish = data.time; ctx.timer(ctx.props.raceTimeout, () => this.endRace(ctx)); }
      const all = Object.values(s.players).every((q) => q.finished);
      if (all) ctx.timer(4, () => this.endRace(ctx));
      this.drawStandings(ctx);
    }
  },
  takeOff(ctx, peerId) {
    const p = ctx.state.players[peerId];
    if (!p) return;
    p.flying = true;
    if (p.entity !== undefined && ctx.world.isAlive(p.entity)) ctx.sendTo(p.entity, 'takeControl', { peer: peerId });
  },

  // -------------------------------------------------------------- race
  resetRace(ctx) {
    const s = ctx.state;
    s.race = { phase: 'idle', startAt: 0, countdown: null, results: {} };
    s.raceFirstFinish = 0;
    for (const p of Object.values(s.players)) { p.gates = 0; p.time = 0; p.finished = 0; }
    ctx.send('raceState', { phase: 'idle' });
    const h = hud(ctx);
    if (h) { h.remove('countdown'); h.remove('race-result'); }
  },
  startRace(ctx) {
    const s = ctx.state;
    if (s.race.phase === 'countdown' || s.race.phase === 'running') return;
    this.resetRace(ctx);
    s.mode = 'race';
    const W = this.world(ctx);
    if (W) for (const [peer, p] of Object.entries(s.players)) { if (p.entity !== undefined && ctx.world.isAlive(p.entity)) ctx.sendTo(p.entity, 'resetTo', { position: W.spawn(p.index).position, yaw: W.spawn(p.index).yaw, peer }); p.flying = true; ctx.sendTo(p.entity, 'takeControl', { peer }); }
    s.race.phase = 'countdown';
    ctx.send('raceState', { phase: 'countdown' });
    this.spawnGhost(ctx);
    let n = ctx.props.countdown;
    const h = hud(ctx);
    const tick = () => {
      if (n > 0) {
        s.race.countdown = String(n);
        if (h) h.text('countdown', s.race.countdown, { anchor: 'center' }).style.cssText += 'font-size:96px;font-weight:200;letter-spacing:0.1em;';
        ctx.audio.play('tick', { volume: 0.5 });
        n--;
        this.drawStandings(ctx);
        ctx.timer(1, tick);
      } else {
        s.race.countdown = 'GO';
        s.race.phase = 'running';
        s.race.startAt = ctx.time.elapsed;
        if (h) h.text('countdown', 'GO', { anchor: 'center' });
        ctx.audio.play('go', { volume: 0.6 });
        ctx.send('raceState', { phase: 'running', startAt: s.race.startAt });
        ctx.send('nextGate', { index: 0, peer: ctx.net.localId });
        ctx.timer(1, () => { s.race.countdown = null; if (h) h.remove('countdown'); this.drawStandings(ctx); });
        this.drawStandings(ctx);
      }
    };
    tick();
  },
  endRace(ctx) {
    const s = ctx.state;
    if (s.race.phase !== 'running') return;
    s.race.phase = 'finished';
    ctx.send('raceState', { phase: 'finished' });
    this.drawStandings(ctx);
    ctx.timer(6, () => { if (s.race.phase === 'finished') { this.resetRace(ctx); s.mode = 'free'; this.drawStandings(ctx); } });
  },
  /** Local: replay the stored best run for this seed as a translucent glider. */
  spawnGhost(ctx) {
    const P = pg(ctx), W = this.world(ctx);
    if (!P || !W || !ctx.engine.canvas) return;
    const raw = P.env.storageGet(`driftwind.ghost.${W.seed}`);
    if (!raw) return;
    try {
      const path = JSON.parse(raw);
      if (!Array.isArray(path) || path.length < 2) return;
      const e = ctx.spawn('Ghost', { position: { x: path[0][0], y: path[0][1], z: path[0][2] }, name: 'Ghost' });
      ctx.getOn(e, 'Script').props.path = path;
    } catch (err) { ctx.warn(`Ghost data unreadable: ${err}`); }
  },

  // ----------------------------------------------------------- HUD / RPC
  broadcastHud(ctx, payload) {
    if (!ctx.net.isHost || !ctx.net.online) return;
    const json = JSON.stringify(payload);
    if (json === ctx.state.lastHud) return;
    ctx.state.lastHud = json;
    ctx.net.rpc('hud', [payload], 'others');
  },
  resendHud(ctx) { ctx.state.lastHud = null; this.drawStandings(ctx); },
  onRpc(ctx, name, args, from) {
    const s = ctx.state;
    if (name === 'fly' && ctx.net.isHost) { this.takeOff(ctx, from); return; }
    if (name === 'requestRace' && ctx.net.isHost) { this.startRace(ctx); return; }
    if (name !== 'hud' || ctx.net.isHost) return;
    const d = args[0];
    const wasRunning = s.race.phase === 'running';
    s.players = d.players;
    s.race = d.race;
    s.mode = d.mode;
    if (d.seed && d.seed !== s.seed) { s.seed = d.seed; ctx.send('worldSeed', { seed: d.seed, remote: true }); }
    if (d.race.phase === 'running' && !wasRunning) { ctx.send('raceState', { phase: 'running', startAt: ctx.time.elapsed - (d.race.elapsed || 0) }); this.spawnGhost(ctx); }
    if (d.race.phase === 'idle' && wasRunning) ctx.send('raceState', { phase: 'idle' });
    const me = d.players[ctx.net.localId];
    if (me && me.finished && !s.reportedFinish) { s.reportedFinish = me.finished; const P = pg(ctx); const prev = P ? Number(P.env.storageGet(`driftwind.best.${s.seed}`) || 0) : 0; ctx.send('raceResult', { peer: ctx.net.localId, time: me.finished, best: !prev || me.finished < prev }); }
    if (d.race.phase !== 'running') s.reportedFinish = 0;
    const h = hud(ctx);
    if (h) { if (d.race.countdown) h.text('countdown', d.race.countdown, { anchor: 'center' }).style.cssText += 'font-size:96px;font-weight:200;letter-spacing:0.1em;'; else h.remove('countdown'); }
    this.drawStandings(ctx);
  },
  drawStandings(ctx) {
    const s = ctx.state;
    const rows = {};
    for (const [id, p] of Object.entries(s.players)) rows[id] = { index: p.index, label: p.label, gates: p.gates, time: p.time, finished: p.finished };
    this.broadcastHud(ctx, { players: rows, race: { phase: s.race.phase, countdown: s.race.countdown || null, elapsed: s.race.phase === 'running' ? ctx.time.elapsed - s.race.startAt : 0, results: s.race.results }, mode: s.mode, seed: s.seed });
    const h = hud(ctx);
    if (!h) return;
    const list = Object.values(s.players);
    if (s.race.phase === 'idle' || list.length === 0) { h.remove('standings'); h.remove('race-result'); return; }
    const me = ctx.net.localId;
    const sorted = list.slice().sort((a, b) => (b.finished ? 1e6 - b.finished : b.gates) - (a.finished ? 1e6 - a.finished : a.gates) || a.time - b.time);
    const lines = sorted.map((p, i) => `${i + 1}.  ${p.label}${Object.keys(s.players).find((k) => s.players[k] === p) === me ? ' (you)' : ''}   ${p.finished ? p.finished.toFixed(2) + 's' : `gate ${p.gates}`}`);
    const el = h.text('standings', lines.join('\n'), { anchor: 'top-right', y: 48, x: 14 });
    el.style.cssText += 'font-size:13px;letter-spacing:0.08em;line-height:1.7;opacity:0.9;font-variant-numeric:tabular-nums;text-align:right;';
    const mine = s.players[me];
    if (s.race.phase === 'finished' || (mine && mine.finished)) {
      const P = pg(ctx);
      const best = P ? P.env.storageGet(`driftwind.best.${s.seed}`) : null;
      const t = mine && mine.finished ? `${mine.finished.toFixed(2)}s` : 'did not finish';
      h.text('race-result', `${t}${best ? `   ·   best ${Number(best).toFixed(2)}s` : ''}`, { anchor: 'center', y: 40 }).style.cssText += 'font-size:22px;font-weight:300;letter-spacing:0.12em;text-align:center;';
    } else h.remove('race-result');
  },
});

// Replays a recorded race run (positions + rotations sampled every 0.1 s) as
// a translucent glider, so you race your own best time.
function pg(ctx) { return ctx.engine.procgen || null; }

defineScript({
  name: 'Ghost',
  description: 'Translucent replay of the best run for this seed.',
  props: {
    path: { type: 'json', default: [] },
    interval: { type: 'number', default: 0.1 },
    livery: { type: 'integer', default: 0 },
  },
  onStart(ctx) {
    const s = ctx.state, P = pg(ctx);
    s.t = 0; s.playing = false;
    const W = P && P.world;
    if (P && W) {
      const key = `${W.seed}:glider-${ctx.props.livery % 6}`;
      const desc = P.registered(key) || P.registerGenerated(key, W.library(`glider-${ctx.props.livery % 6}`));
      for (const g of desc.groups) {
        const c = ctx.world.createEntity(g.name);
        ctx.world.setParent(c, ctx.entity);
        const mr = ctx.world.addComponentByType(c, 'MeshRenderer', { mesh: g.mesh });
        P.applyMaterial(mr, g);
        mr.opacity = 0.3;
        mr.color.set(0.7, 0.9, 1, 1);
        mr.emissive.set(0.25, 0.45, 0.6, 1);
      }
    }
    s.qa = new ctx.math.Quat(); s.qb = new ctx.math.Quat();
    this.apply(ctx, 0);
  },
  onMessage(ctx, name, data) {
    if (name === 'raceState') {
      if (data.phase === 'running') { ctx.state.t = ctx.time.elapsed - data.startAt; ctx.state.playing = true; ctx.state.startAt = data.startAt; }
      else if (data.phase === 'idle') ctx.destroy();
    }
  },
  apply(ctx, time) {
    const path = ctx.props.path;
    if (!path || path.length === 0) return;
    const f = time / ctx.props.interval;
    const i = Math.min(path.length - 1, Math.max(0, Math.floor(f)));
    const j = Math.min(path.length - 1, i + 1);
    const k = Math.min(1, Math.max(0, f - i));
    const a = path[i], b = path[j];
    const t = ctx.transform;
    t.setPosition(a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k);
    const s = ctx.state;
    s.qa.set(a[3], a[4], a[5], a[6]); s.qb.set(b[3], b[4], b[5], b[6]);
    s.qa.slerp(s.qb, k);
    t.rotation.copy(s.qa);
    t.markDirty();
    for (const c of ctx.world.getChildren(ctx.entity)) { const mr = ctx.getOn(c, 'MeshRenderer'); if (mr) mr.visible = f < path.length + 5; }
  },
  onUpdate(ctx) {
    const s = ctx.state;
    if (!s.playing) return;
    this.apply(ctx, ctx.time.elapsed - s.startAt);
  },
});

// The player's glider: an arcade flight model (bank to turn, dive to gain
// speed, climb to trade it back, stall when too slow), boost meter fed by rings
// and wind currents, soft collisions with islands, gate/mote detection and the
// flight HUD. All movement happens in onOwnerInput so only the simulating peer
// integrates; remote copies just show the replicated transform.
function hud(ctx) { return ctx.engine.canvas ? ctx.engine.hud : null; }
function pg(ctx) { return ctx.engine.procgen || null; }
function world(ctx) { const p = pg(ctx); return p ? p.world : null; }
const UP = { x: 0, y: 1, z: 0 }, RIGHT = { x: 1, y: 0, z: 0 }, BACK = { x: 0, y: 0, z: 1 };
const GROUPS = { Hull: 'hull', Wing: 'wing', Trim: 'trim', Canopy: 'canopy' };

defineScript({
  name: 'Glider',
  description: 'Arcade glider flight model with boost, stall, soft collisions, gates and motes.',
  props: {
    livery: { type: 'integer', default: 0, min: 0, max: 5 },
    label: { type: 'string', default: 'P1' },
    heading: { type: 'number', default: 0, label: 'Start heading (rad)' },
    cruise: { type: 'number', default: 30, min: 5, max: 80, label: 'Cruise speed' },
    stall: { type: 'number', default: 15, min: 2, max: 40, label: 'Stall speed' },
    maxSpeed: { type: 'number', default: 68, min: 10, max: 150 },
    pitchRate: { type: 'number', default: 1.5, min: 0.2, max: 5, label: 'Pitch rate (rad/s)' },
    maxBank: { type: 'number', default: 1.05, min: 0.1, max: 1.5, label: 'Max bank (rad)' },
    turnRate: { type: 'number', default: 1.15, min: 0.1, max: 5, label: 'Turn rate at full bank' },
    sink: { type: 'number', default: 2.2, min: 0, max: 10, label: 'Sink rate at cruise' },
    boostAccel: { type: 'number', default: 28, min: 0, max: 100 },
    invertPitch: { type: 'boolean', default: false, label: 'Push forward to climb' },
  },
  onStart(ctx) {
    this.ctxRef = ctx;
    ctx.state.fwdTmp = { x: 0, y: 0, z: 0 };
    const s = ctx.state, p = ctx.props, t = ctx.transform;
    s.speed = p.cruise * 0.85; s.yaw = p.heading; s.pitch = 0; s.bank = 0; s.boost = 0.5; s.stallAmount = 0;
    s.drift = { x: 0, y: 0, z: 0 }; s.windTmp = { x: 0, y: 0, z: 0 }; s.windStrength = 0;
    s.flying = false; s.homeY = t.y;
    s.gates = 0; s.raceGate = 0; s.racing = false; s.raceStart = 0; s.raceTime = 0; s.finished = false;
    s.ringCooldown = {}; s.motes = 0; s.discovered = {}; s.collideCooldown = 0; s.lastPos = { x: t.x, y: t.y, z: t.z };
    s.ghostPath = []; s.ghostTimer = 0; s.hudTick = 0; s.renderSpeed = 0; s.vel = { x: 0, y: 0, z: 0 };
    s.q1 = new ctx.math.Quat(); s.q2 = new ctx.math.Quat();
    this.applyLook(ctx);
    this.orient(ctx);
    if (this.isLocal(ctx)) {
      s.windLoop = ctx.audio.play('wind', { loop: true, volume: 0 });
    }
  },
  onReload(ctx) { this.applyLook(ctx); },
  onDestroy(ctx) {
    const s = ctx.state;
    if (s.windLoop) s.windLoop.stop(0.3);
    const h = hud(ctx);
    if (h && this.isLocal(ctx)) for (const id of ['speed', 'alt', 'boostbar', 'boostbg', 'flight-mode', 'stall']) h.remove(id);
  },
  isLocal(ctx) {
    const pi = ctx.playerInput;
    return !!pi && (pi.owner === 'local' || pi.owner === ctx.net.localId);
  },
  /** Swap the prefab's placeholder meshes for the livery's generated glider groups. */
  applyLook(ctx) {
    const P = pg(ctx), W = world(ctx);
    if (!P || !W) return;
    const key = `${W.seed}:glider-${ctx.props.livery % 6}`;
    const desc = P.registered(key) || P.registerGenerated(key, W.library(`glider-${ctx.props.livery % 6}`));
    for (const child of ctx.world.getChildren(ctx.entity)) {
      const g = GROUPS[ctx.nameOf(child)];
      const mr = ctx.getOn(child, 'MeshRenderer');
      const group = desc.groups.find((x) => x.name === g);
      if (mr && group) {
        mr.mesh = group.mesh;
        P.applyMaterial(mr, group);
        // The generated groups are modelled at full size in the glider's frame: drop the placeholder cube's offset and scale.
        const ct = ctx.getOn(child, 'Transform');
        if (ct) { ct.setPosition(0, 0, 0); ct.setScale(1, 1, 1); ct.rotation.set(0, 0, 0, 1); ct.markDirty(); }
      }
    }
  },
  orient(ctx) {
    const s = ctx.state, t = ctx.transform;
    const q = t.rotation;
    q.setAxisAngle(UP, s.yaw);
    q.multiply(s.q1.setAxisAngle(RIGHT, s.pitch));
    q.multiply(s.q2.setAxisAngle(BACK, -s.bank));
    t.markDirty();
  },
  forward(s) {
    return pg(this.ctxRef).flight.headingForward(s.yaw, s.pitch, s.fwdTmp);
  },
  teleport(ctx, position, yaw) {
    const s = ctx.state;
    ctx.transform.setPosition(position.x, position.y, position.z);
    s.yaw = yaw; s.pitch = 0; s.bank = 0; s.speed = ctx.props.cruise * 0.85; s.drift.x = s.drift.y = s.drift.z = 0;
    s.homeY = position.y; s.lastPos = { x: position.x, y: position.y, z: position.z };
    this.orient(ctx);
  },

  onMessage(ctx, name, data) {
    const s = ctx.state;
    if (name === 'takeControl') { if (data.peer === ctx.net.owner()) { s.flying = true; s.hudCleared = false; } }
    else if (name === 'resetTo') { if (!data.peer || data.peer === ctx.net.owner()) this.teleport(ctx, data.position, data.yaw); }
    else if (name === 'raceState') {
      if (data.phase === 'running') { s.racing = true; s.finished = false; s.raceGate = 0; s.raceStart = data.startAt; s.ghostPath = []; s.ghostTimer = 0; }
      else if (data.phase === 'idle') { s.racing = false; s.finished = false; s.raceGate = 0; }
      else if (data.phase === 'countdown') { s.racing = false; s.finished = false; s.raceGate = 0; }
    } else if (name === 'raceResult') {
      if (data.peer !== ctx.net.owner() || !this.isLocal(ctx)) return;
      s.finished = true; s.raceTime = data.time;
      const P = pg(ctx), W = world(ctx);
      if (P && W && data.best) {
        P.env.storageSet(`driftwind.best.${W.seed}`, String(data.time));
        if (s.ghostPath.length > 2) P.env.storageSet(`driftwind.ghost.${W.seed}`, JSON.stringify(s.ghostPath));
      }
    } else if (name === 'worldSeed') { s.discovered = {}; s.gates = 0; s.motes = 0; ctx.timer(0.05, () => this.applyLook(ctx)); }
  },

  onOwnerInput(ctx, snap, dt) {
    const s = ctx.state, p = ctx.props, t = ctx.transform, M = ctx.math;
    const P = pg(ctx);
    if (!P) return;
    const FL = P.flight;
    const W = world(ctx);
    let steer = 0, pitchIn = 0, boosting = false, braking = false;
    if (s.flying) {
      steer = snap.axes.moveX || 0;
      pitchIn = (snap.axes.moveY || 0) * (p.invertPitch ? -1 : 1);
      boosting = snap.held.includes('boost');
      braking = snap.held.includes('brake');
    } else {
      // Autopilot before the player takes off: a lazy S-curve holding altitude.
      steer = Math.sin(ctx.time.elapsed * 0.22 + s.yaw) * 0.3;
      pitchIn = M.clamp((s.homeY - t.y) * 0.06 - (s.speed - p.cruise) * 0.01, -0.35, 0.35);
    }
    // Bank and turn (banking turns; slower at high speed like a real wing).
    s.bank = M.damp(s.bank, M.clamp(steer, -1, 1) * p.maxBank, 3.2, dt);
    s.yaw += FL.bankTurnRate(s.bank, p.turnRate, s.speed, p.cruise) * dt;
    // Pitch with reduced authority near the stall, natural nose-down tendency.
    const authority = M.clamp((s.speed - p.stall * 0.6) / (p.cruise - p.stall * 0.6), 0.15, 1);
    s.pitch += pitchIn * p.pitchRate * authority * dt;
    if (Math.abs(pitchIn) < 0.05) s.pitch = M.damp(s.pitch, -0.04, 0.9, dt);
    if (s.speed < p.stall) { s.pitch -= ((p.stall - s.speed) / p.stall) * 2.4 * dt; s.stallAmount = Math.min(1, s.stallAmount + dt * 2.5); }
    else s.stallAmount = Math.max(0, s.stallAmount - dt * 2);
    s.pitch = M.clamp(s.pitch, -1.2, 0.95);
    // Speed: gravity along the flight path, aero drag/lift settling toward cruise, boost and brake.
    const boostOn = boosting && s.boost > 0.001;
    if (boostOn) { s.boost = Math.max(0, s.boost - dt * 0.42); if (!s.wasBoosting && this.isLocal(ctx)) ctx.audio.play('whoosh', { volume: 0.5 }); }
    else s.boost = Math.min(1, s.boost + dt * 0.03);
    s.wasBoosting = boostOn;
    s.speed = FL.integrateSpeed(s.speed, s.pitch, dt, { cruise: p.cruise, stall: p.stall, maxSpeed: p.maxSpeed, boostAccel: p.boostAccel, boosting: boostOn, braking });
    if (braking) s.pitch += 0.35 * authority * dt;
    // Wind currents push the glider along and refill the boost meter.
    let wind = s.windTmp;
    if (W) W.windAt(t.position, wind); else { wind.x = wind.y = wind.z = 0; }
    s.windStrength = Math.hypot(wind.x, wind.y, wind.z);
    s.drift.x += wind.x * dt; s.drift.y += wind.y * dt; s.drift.z += wind.z * dt;
    const dk = Math.exp(-1.3 * dt);
    s.drift.x *= dk; s.drift.y *= dk; s.drift.z *= dk;
    if (s.windStrength > 1) s.boost = Math.min(1, s.boost + dt * 0.14);
    // Velocity: along the nose, plus drift, minus sink (stronger when slow).
    const f = this.forward(s);
    const sink = p.sink * M.clamp(p.cruise / Math.max(s.speed, 6), 0.35, 3.5);
    let vx = f.x * s.speed + s.drift.x, vy = f.y * s.speed + s.drift.y - sink, vz = f.z * s.speed + s.drift.z;
    // Soft ceiling and floor, with an updraft recovery under the archipelago.
    const B = W ? W.bounds : { minY: -40, maxY: 140 };
    const ceiling = B.maxY + 70, floor = B.minY - 40;
    if (t.y > ceiling) { s.pitch -= (t.y - ceiling) * 0.02 * dt; vy -= (t.y - ceiling) * 0.6; }
    if (t.y < floor) { s.pitch += (floor - t.y) * 0.04 * dt; vy += (floor - t.y) * 0.9; s.speed = Math.max(s.speed, p.cruise); s.boost = Math.min(1, s.boost + dt * 0.6); }
    if (t.y < floor - 220 && W) { const sp = W.spawn(0); this.teleport(ctx, sp.position, sp.yaw); return; }
    s.lastPos.x = t.x; s.lastPos.y = t.y; s.lastPos.z = t.z;
    t.position.x += vx * dt; t.position.y += vy * dt; t.position.z += vz * dt;
    s.vel.x = vx; s.vel.y = vy; s.vel.z = vz;
    // Soft collision: push out, deflect the nose, lose speed, keep flying.
    s.collideCooldown -= dt;
    if (W && s.collideCooldown <= 0) {
      const hit = W.collide(t.position, 1.4);
      if (hit) {
        t.position.x += hit.push.x; t.position.y += hit.push.y; t.position.z += hit.push.z;
        const n = hit.normal;
        // Blend the reflected direction with the current heading so it feels like a bounce, not a ricochet.
        const bounce = FL.bounceHeading(s.vel, f, n);
        if (bounce) { s.yaw = bounce.yaw; s.pitch = bounce.pitch; }
        const strength = M.clamp(s.speed / p.maxSpeed, 0.2, 1);
        s.speed = Math.max(p.stall * 0.95, s.speed * 0.5);
        s.drift.x += n.x * 5; s.drift.y += n.y * 5; s.drift.z += n.z * 5;
        s.collideCooldown = 0.45;
        ctx.send('collision', { peer: ctx.net.owner(), strength, position: { x: t.x, y: t.y, z: t.z }, normal: n });
        if (this.isLocal(ctx)) ctx.audio.play('thud', { volume: 0.4 + strength * 0.5, pitchVariation: 0.1 });
      }
    }
    t.markDirty();
    this.orient(ctx);
    if (W) this.checkGates(ctx, W, s.lastPos, t.position);
  },

  /** Segment test against every gate ring: did we fly through it this step? */
  checkGates(ctx, W, a, b) {
    const s = ctx.state, FL = pg(ctx).flight;
    for (const ring of W.rings) {
      const c = ring.position;
      const dx = b.x - c.x, dz = b.z - c.z;
      if (dx * dx + dz * dz > 900) continue;
      const cross = FL.gateCrossing(a, b, ring);
      if (!cross) continue;
      const forwardPass = cross.forward;
      const now = ctx.time.elapsed;
      if (s.racing && !s.finished) {
        if (ring.index !== s.raceGate || !forwardPass) continue;
        s.raceGate++;
        const time = now - s.raceStart;
        s.boost = Math.min(1, s.boost + 0.35);
        ctx.send('gatePassed', { peer: ctx.net.owner(), index: ring.index, time, total: W.rings.length });
        if (s.raceGate >= W.rings.length) ctx.send('raceFinished', { peer: ctx.net.owner(), time });
        if (this.isLocal(ctx)) ctx.audio.play('chime', { volume: 0.6 });
        ctx.send('ringPassed', { index: ring.index, peer: ctx.net.owner() });
      } else {
        if ((s.ringCooldown[ring.index] || -10) > now - 3) continue;
        s.ringCooldown[ring.index] = now;
        s.gates++;
        s.boost = Math.min(1, s.boost + 0.35);
        s.speed = Math.min(ctx.props.maxSpeed, s.speed + 6);
        if (this.isLocal(ctx)) ctx.audio.play('chime', { volume: 0.5, pitchVariation: 0.05 });
        ctx.send('ringPassed', { index: ring.index, peer: ctx.net.owner() });
      }
    }
  },

  onUpdate(ctx, dt) {
    const s = ctx.state, t = ctx.transform;
    if (!this.isLocal(ctx)) return;
    // Render-side speed (works for host-simulated remote copies too).
    if (dt > 0) {
      const d = Math.hypot(t.x - (s.rx ?? t.x), t.y - (s.ry ?? t.y), t.z - (s.rz ?? t.z)) / dt;
      s.renderSpeed = ctx.math.damp(s.renderSpeed, Math.min(d, 200), 6, dt);
    }
    s.rx = t.x; s.ry = t.y; s.rz = t.z;
    const W = world(ctx);
    if (s.windLoop) s.windLoop.setVolume(ctx.math.clamp(0.08 + s.renderSpeed / 90, 0, 0.75) * (s.flying ? 1 : 0.5));
    if (W && s.flying) this.collectAround(ctx, W);
    if (s.racing && !s.finished) {
      s.ghostTimer += dt;
      if (s.ghostTimer >= 0.1) {
        s.ghostTimer -= 0.1;
        const q = t.rotation;
        s.ghostPath.push([+t.x.toFixed(2), +t.y.toFixed(2), +t.z.toFixed(2), +q.x.toFixed(3), +q.y.toFixed(3), +q.z.toFixed(3), +q.w.toFixed(3)]);
      }
    }
    if (ctx.time.frame % 4 === 0) {
      if (s.flying) this.drawHud(ctx);
      else if (!s.hudCleared) { s.hudCleared = true; const h = hud(ctx); if (h) for (const id of ['speed', 'alt', 'boostbg', 'boostbar', 'stall', 'flight-mode']) h.remove(id); }
    }
  },

  /** Motes and island discovery are local flavour: only the local player's own glider collects. */
  collectAround(ctx, W) {
    const s = ctx.state, t = ctx.transform;
    for (const e of ctx.findAll('mote')) {
      const mt = ctx.getOn(e, 'Transform');
      if (!mt) continue;
      const dx = mt.x - t.x, dy = mt.y - t.y, dz = mt.z - t.z;
      if (dx * dx + dy * dy + dz * dz < 6.5) {
        s.motes++;
        s.boost = Math.min(1, s.boost + 0.12);
        ctx.destroy(e);
        ctx.audio.play('mote', { volume: 0.45, pitchVariation: 0.08 });
        ctx.send('moteCollected', { count: s.motes, position: { x: mt.x, y: mt.y, z: mt.z } });
      }
    }
    if (ctx.time.frame % 15 === 0) {
      const near = W.nearestIsland(t.position);
      if (near && near.distance < 26 && !s.discovered[near.island.id]) {
        s.discovered[near.island.id] = true;
        const count = Object.keys(s.discovered).length;
        ctx.send('discover', { name: near.island.name, biome: near.island.biome, count, total: W.islands.length });
        ctx.audio.play('discover', { volume: 0.4 });
      }
    }
  },

  drawHud(ctx) {
    const h = hud(ctx);
    if (!h) return;
    const s = ctx.state, t = ctx.transform;
    const speed = Math.round(s.renderSpeed * 3.6);
    const W = world(ctx);
    const ground = W ? W.groundBelow(t.position) : null;
    const alt = Math.max(0, Math.round(t.y - (ground ? ground.y : (W ? W.bounds.minY - 40 : 0))));
    const el = h.text('speed', `${speed}`, { anchor: 'bottom', y: 54, x: 0 });
    el.style.cssText += 'font-size:44px;font-weight:200;letter-spacing:0.04em;text-align:center;line-height:1;font-variant-numeric:tabular-nums;';
    const alte = h.text('alt', `${alt} m  ·  ${ground ? 'over ' + ground.island.name : 'open sky'}`, { anchor: 'bottom', y: 40, x: 0 });
    alte.style.cssText += 'font-size:12px;letter-spacing:0.18em;text-transform:uppercase;opacity:0.75;text-align:center;';
    const bg = h.text('boostbg', '', { anchor: 'bottom', y: 26, x: 0 });
    bg.style.cssText += 'width:180px;height:4px;border-radius:2px;background:rgba(255,255,255,0.18);';
    const bar = h.text('boostbar', '', { anchor: 'bottom', y: 26, x: 0 });
    const w = Math.round(180 * s.boost);
    bar.style.cssText += `height:4px;border-radius:2px;background:linear-gradient(90deg,#ffd166,#ff7a3d);box-shadow:0 0 12px rgba(255,209,102,0.6);transition:width 0.1s;`;
    bar.style.width = `${w}px`;
    bar.style.marginLeft = `${-90 + w / 2}px`;
    bg.style.marginLeft = '0px';
    const stall = h.text('stall', s.stallAmount > 0.2 && s.flying ? 'STALL  ·  dive to recover' : '', { anchor: 'center', y: -70, x: 0 });
    stall.style.cssText += 'font-size:13px;letter-spacing:0.25em;color:#ffd166;text-align:center;';
    stall.style.opacity = String(s.stallAmount);
    let mode = '';
    if (s.racing && !s.finished) mode = `Gate ${Math.min(s.raceGate + 1, W ? W.rings.length : 0)} / ${W ? W.rings.length : 0}   ${(ctx.time.elapsed - s.raceStart).toFixed(1)}s`;
    else if (s.finished) mode = `Finished  ${s.raceTime.toFixed(2)}s`;
    else if (s.flying) mode = `${s.motes} motes  ·  ${Object.keys(s.discovered).length}/${W ? W.islands.length : 0} islands  ·  ${s.gates} rings`;
    const me = h.text('flight-mode', mode, { anchor: 'top-left', y: 12, x: 14 });
    me.style.cssText += 'font-size:13px;letter-spacing:0.12em;opacity:0.85;font-variant-numeric:tabular-nums;';
  },
});

// Marker on every streamed island so tools, other scripts and the editor can
// see what it is (name, biome, radius). The geometry itself is generated by
// the WorldStreamer from the world seed.
defineScript({
  name: 'Island',
  description: 'Identifies a generated floating island.',
  props: {
    id: { type: 'integer', default: 0 },
    name: { type: 'string', default: 'Island' },
    biome: { type: 'string', default: 'meadow' },
    radius: { type: 'number', default: 18 },
  },
});

// Race gate visuals: the glowing segments pulse, flash white when a glider
// flies through and settle to green once the local player passed the gate in a
// race. Detection lives in the Glider script (segment vs. gate plane).
defineScript({
  name: 'Ring',
  description: 'Gate ring glow and pass feedback.',
  props: { index: { type: 'integer', default: 0 } },
  onStart(ctx) {
    const s = ctx.state;
    s.glow = [];
    for (const c of ctx.world.getChildren(ctx.entity)) {
      const mr = ctx.getOn(c, 'MeshRenderer');
      if (mr && ctx.nameOf(c) === 'ring-glow') { s.glow.push(mr); s.base = mr.color.clone(); }
    }
    s.flash = 0; s.passed = false; s.next = false;
  },
  onMessage(ctx, name, data) {
    const s = ctx.state;
    if (name === 'ringPassed' && data.index === ctx.props.index) { s.flash = 1; if (data.peer === ctx.net.localId || data.peer === 'local') s.passed = true; }
    else if (name === 'raceState') { s.passed = false; s.next = false; }
    else if (name === 'nextGate') s.next = data.index === ctx.props.index;
  },
  onUpdate(ctx, dt) {
    const s = ctx.state;
    if (!s.glow || !s.glow.length) return;
    s.flash = Math.max(0, s.flash - dt * 2.2);
    const pulse = 0.55 + 0.45 * Math.sin(ctx.time.elapsed * 2.5 + ctx.props.index * 0.9);
    for (const mr of s.glow) {
      if (s.passed) mr.color.set(0.45, 0.95, 0.6, 1);
      else if (s.next) mr.color.set(1, 1, 1, 1).lerp(s.base, 0.35 + 0.35 * pulse);
      else mr.color.copy(s.base);
      const k = (s.next ? 0.7 : 0.35) + 0.35 * pulse + s.flash * 0.8;
      mr.emissive.set(mr.color.r * k, mr.color.g * k, mr.color.b * k, 1);
    }
  },
});

// Start screen and notifications: title, seed field, Fly / Race / Play with
// friends / Daily seed / Random seed, control hints, island discovery toasts,
// photo-mode HUD hiding. Talks to the GameManager with messages
// (shell:fly, shell:race, shell:seed). Everything degrades to no-ops headless.
function hud(ctx) { return ctx.engine.canvas ? ctx.engine.hud : null; }
function pg(ctx) { return ctx.engine.procgen || null; }

const FONT = "font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif;";

defineScript({
  name: 'Shell',
  description: 'Start screen, seed picker and notifications.',
  props: {
    title: { type: 'string', default: 'DRIFTWIND' },
    tagline: { type: 'string', default: 'A gliding journey through a floating archipelago' },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.open = false; s.started = false; s.toastTimer = null;
    const h = hud(ctx);
    if (!h) return;
    h.root.style.transition = 'opacity 0.4s';
    this.showStart(ctx);
  },
  onDestroy(ctx) {
    const h = hud(ctx);
    if (h) for (const id of ['start', 'toast', 'hints', 'controls', 'flash']) h.remove(id);
  },
  seedNow(ctx) {
    const P = pg(ctx);
    return P && P.world ? P.world.seed : 'amber-lagoon-42';
  },
  showStart(ctx) {
    const h = hud(ctx), s = ctx.state, P = pg(ctx);
    if (!h) return;
    s.open = true;
    const panel = h.panel('start', ctx.props.title, ctx.props.tagline);
    panel.style.cssText += `${FONT}background:rgba(14,16,28,0.55);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,0.14);border-radius:18px;padding:34px 44px 30px;min-width:340px;box-shadow:0 30px 80px rgba(0,0,0,0.45);`;
    const title = panel.firstChild;
    title.style.cssText = 'font-size:46px;font-weight:200;letter-spacing:0.32em;margin:0 0 6px;background:linear-gradient(90deg,#ffd166,#ff7a3d 55%,#ff8bd1);-webkit-background-clip:text;background-clip:text;color:transparent;';
    if (panel.children[1]) panel.children[1].style.cssText = 'font-size:13px;letter-spacing:0.14em;opacity:0.72;margin-bottom:22px;';
    const guest = ctx.net.online && !ctx.net.isHost;
    // Seed row: an editable label (scripts have no document access; the overlay builds the element).
    const seedLabel = h.text('start-seed-label', guest ? 'world seed (set by the host)' : 'world seed', {});
    seedLabel.style.cssText = 'position:static;margin:0 0 4px;font-size:11px;letter-spacing:0.22em;text-transform:uppercase;opacity:0.6;text-align:left;';
    panel.appendChild(seedLabel);
    const seed = h.text('start-seed', P && P.seeds ? P.seeds.seedTitle(this.seedNow(ctx)) : this.seedNow(ctx), {});
    seed.style.cssText = `position:static;margin:0 0 18px;padding:10px 14px;border-radius:10px;background:rgba(255,255,255,${guest ? 0.05 : 0.1});border:1px solid rgba(255,255,255,0.18);font-size:18px;letter-spacing:0.08em;text-align:left;pointer-events:${guest ? 'none' : 'auto'};outline:none;min-width:280px;`;
    if (!guest) { seed.contentEditable = 'true'; seed.spellcheck = false; seed.setAttribute('aria-label', 'World seed'); seed.setAttribute('role', 'textbox'); }
    panel.appendChild(seed);
    s.seedEl = seed;
    const row = (id) => { const r = h.text(id, '', {}); r.style.cssText = 'position:static;display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin:0 0 10px;'; panel.appendChild(r); return r; };
    const primary = row('start-row-1');
    const secondary = row('start-row-2');
    const mk = (id, label, fn, big, into) => {
      const b = h.button(id, label, fn, {});
      b.style.cssText = `position:static;margin:0;${FONT}pointer-events:auto;cursor:pointer;border-radius:10px;padding:${big ? '12px 26px' : '8px 14px'};font-size:${big ? 15 : 12}px;letter-spacing:0.08em;border:1px solid rgba(255,255,255,0.22);background:${big ? 'linear-gradient(90deg,#ff7a3d,#ffb347)' : 'rgba(255,255,255,0.08)'};color:${big ? '#1a0d05' : '#fff'};font-weight:${big ? 600 : 500};`;
      into.appendChild(b);
      return b;
    };
    mk('start-fly', 'Fly', () => this.start(ctx, 'fly'), true, primary);
    mk('start-race', guest ? 'Ask host to race' : 'Race', () => this.start(ctx, 'race'), true, primary);
    mk('start-friends', ctx.net.online ? 'Copy invite link' : 'Play with friends', () => this.friends(ctx), false, secondary);
    if (!guest) {
      mk('start-daily', 'Daily seed', () => this.setSeed(ctx, P ? P.seeds.dailySeed() : 'daily'), false, secondary);
      mk('start-random', 'Random seed', () => this.setSeed(ctx, P ? P.seeds.randomSeed() : 'random'), false, secondary);
    }
    const hint = h.text('start-hint', P && P.env.isTouch ? 'Left joystick to fly  ·  Boost and Brake buttons' : 'A / D bank   ·   W / S pitch   ·   Space boost   ·   X brake   ·   P photo mode   ·   Enter to fly', {});
    hint.style.cssText = 'position:static;margin:14px 0 0;font-size:11px;letter-spacing:0.12em;opacity:0.55;text-align:center;';
    panel.appendChild(hint);
    for (const id of ['start-seed-label', 'start-seed', 'start-row-1', 'start-row-2', 'start-hint']) { const el = h.get(id); if (el) el.style.position = 'static'; }
  },
  readSeed(ctx) {
    const s = ctx.state, P = pg(ctx);
    const raw = s.seedEl ? String(s.seedEl.textContent || '') : '';
    return P ? P.seeds.normalizeSeed(raw || this.seedNow(ctx)) : raw;
  },
  setSeed(ctx, seed) {
    const s = ctx.state, P = pg(ctx);
    if (s.seedEl) s.seedEl.textContent = P ? P.seeds.seedTitle(seed) : seed;
    ctx.send('shell:seed', { seed });
  },
  start(ctx, mode) {
    const s = ctx.state, h = hud(ctx), P = pg(ctx);
    if (!s.open) return;
    const seed = this.readSeed(ctx);
    if (P && P.world && seed !== P.world.seed && !(ctx.net.online && !ctx.net.isHost)) ctx.send('shell:seed', { seed });
    s.open = false; s.started = true;
    if (h) h.remove('start');
    ctx.send(mode === 'race' ? 'shell:race' : 'shell:fly', {});
    ctx.audio.music('pad', { volume: 0.32, fade: 2, loop: true });
    if (h) {
      const c = h.text('controls', P && P.env.isTouch ? 'joystick: bank + pitch   ·   BOOST   ·   BRAKE' : 'A / D bank   ·   W / S pitch   ·   Space boost   ·   X brake   ·   P photo   ·   R race   ·   Esc menu', { anchor: 'bottom', y: 8 });
      c.style.cssText += 'font-size:11px;letter-spacing:0.14em;opacity:0.5;text-align:center;';
      ctx.timer(7, () => { const el = h.get('controls'); if (el) { el.style.transition = 'opacity 1.5s'; el.style.opacity = '0'; } });
    }
  },
  friends(ctx) {
    const P = pg(ctx);
    if (!P) return;
    if (ctx.net.online) {
      const url = P.env.urlWith({ seed: this.seedNow(ctx), name: null });
      P.env.copyText(url).then((ok) => this.toast(ctx, ok ? 'Invite link copied' : url));
    } else {
      // Open a fresh room with this seed; the lobby shows the invite link.
      const room = Math.random().toString(36).slice(2, 8).toUpperCase();
      P.env.navigate(P.env.urlWith({ room, seed: this.readSeed(ctx) }));
    }
  },
  toast(ctx, text, seconds = 3.5) {
    const h = hud(ctx), s = ctx.state;
    if (!h) return;
    const el = h.text('toast', text, { anchor: 'top', y: 64 });
    el.style.cssText += `${FONT}font-size:15px;letter-spacing:0.16em;padding:10px 18px;border-radius:999px;background:rgba(14,16,28,0.45);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,0.14);transition:opacity 0.6s;`;
    el.style.opacity = '1';
    if (s.toastTimer) s.toastTimer.cancel();
    s.toastTimer = ctx.timer(seconds, () => { const t = h.get('toast'); if (t) t.style.opacity = '0'; });
  },
  onMessage(ctx, name, data) {
    const h = hud(ctx);
    if (name === 'discover') this.toast(ctx, `${data.name}   ·   ${data.count} / ${data.total} islands`);
    else if (name === 'photoMode' && h) h.root.style.opacity = data.on ? '0' : '1';
    else if (name === 'raceState' && data.phase === 'finished' && !ctx.state.open) this.toast(ctx, 'Race over  ·  press R to race again', 5);
    else if (name === 'worldSeed' && data.remote) this.toast(ctx, `Host chose ${pg(ctx).seeds.seedTitle(data.seed)}`);
    else if (name === 'collision' && h && (data.peer === ctx.net.localId || data.peer === 'local')) {
      const f = h.text('flash', '', { anchor: 'top-left', x: 0, y: 0 });
      f.style.cssText = 'position:absolute;inset:0;margin:0;background:radial-gradient(circle,rgba(255,255,255,0) 40%,rgba(255,235,210,0.5) 100%);transition:opacity 0.5s;pointer-events:none;';
      f.style.opacity = String(Math.min(1, 0.5 + data.strength));
      ctx.timer(0.08, () => { const el = h.get('flash'); if (el) el.style.opacity = '0'; });
    }
  },
  onUpdate(ctx) {
    const s = ctx.state, h = hud(ctx);
    if (!h) return;
    if (s.open) {
      if (ctx.input.keyboard.pressed('Enter') || ctx.input.keyboard.pressed('NumpadEnter')) this.start(ctx, 'fly');
    } else {
      if (ctx.input.keyboard.pressed('KeyR')) ctx.send('shell:race', {});
      if (ctx.input.keyboard.pressed('Escape')) this.showStart(ctx);
    }
  },
});

// Golden hour that never ends: the SkySettings component (procedural sky, sun,
// hemisphere ambient and height fog) is kept drifting slowly around sunset,
// and PostProcessSettings adds the filmic look. Without those components
// (older renderer or headless) the legacy path drives the camera gradient,
// linear fog and the Sun / Ambient lights from the palette's sky presets.
function pg(ctx) { return ctx.engine.procgen || null; }

defineScript({
  name: 'Sky',
  description: 'Time-of-day drift around golden hour; drives sky, fog, sun and post-processing.',
  props: {
    hour: { type: 'number', default: 17.5, min: 0, max: 24, label: 'Centre hour' },
    driftHours: { type: 'number', default: 0.55, min: 0, max: 12, label: 'Drift amplitude (hours)' },
    driftPeriod: { type: 'number', default: 540, min: 10, max: 7200, label: 'Drift period (seconds)' },
    fogNear: { type: 'number', default: 140, min: 0, max: 2000, label: 'Legacy fog near' },
    fogFar: { type: 'number', default: 520, min: 10, max: 5000, label: 'Legacy fog far' },
    paused: { type: 'boolean', default: false },
  },
  onStart(ctx) {
    const s = ctx.state, P = pg(ctx);
    s.elapsed = 0;
    s.dir = new ctx.math.Vec3();
    s.sky = ctx.get('SkySettings') || null;
    // ?time=HH.H pins the hour (screenshots, share links).
    const pinned = P ? parseFloat(P.env.param('time') || '') : NaN;
    s.pinned = Number.isFinite(pinned) ? ((pinned % 24) + 24) % 24 : null;
    if (s.sky) {
      s.sky.enabled = true;
      // Fog: thin and warm around the islands, thickening toward the sea far below.
      const W = P && P.world;
      s.sky.fogHeight = W ? W.bounds.minY - 360 : -360;
      const cam = this.camera(ctx);
      if (cam) cam.fogEnabled = false;
    }
    this.apply(ctx);
  },
  camera(ctx) {
    const camE = ctx.find('Camera');
    return camE !== undefined ? ctx.getOn(camE, 'Camera3D') : undefined;
  },
  hourNow(ctx) {
    const s = ctx.state;
    if (s.pinned !== null) return s.pinned;
    return ctx.props.hour + Math.sin((s.elapsed / ctx.props.driftPeriod) * Math.PI * 2) * ctx.props.driftHours;
  },
  onUpdate(ctx, dt) {
    if (!ctx.props.paused) ctx.state.elapsed += dt;
    if (ctx.time.frame % 2 === 0) this.apply(ctx);
  },
  apply(ctx) {
    const s = ctx.state;
    const hour = this.hourNow(ctx);
    if (s.sky) { s.sky.timeOfDay = hour; return; }
    this.legacy(ctx, hour / 24);
  },
  /** Pre-SkySettings renderers: gradient sky, linear fog and palette-driven lights. */
  legacy(ctx, t) {
    const P = pg(ctx);
    if (!P) return;
    const sky = P.palettes.skyAt(t);
    const cam = this.camera(ctx);
    if (cam) {
      cam.skyTop.set(sky.top.r, sky.top.g, sky.top.b, 1);
      cam.skyBottom.set(sky.horizon.r, sky.horizon.g, sky.horizon.b, 1);
      cam.fogColor.set(sky.fog.r, sky.fog.g, sky.fog.b, 1);
      cam.clearColor.set(sky.fog.r, sky.fog.g, sky.fog.b, 1);
      cam.fogEnabled = true; cam.fogNear = ctx.props.fogNear; cam.fogFar = ctx.props.fogFar;
    }
    const sunE = ctx.find('Sun');
    if (sunE !== undefined) {
      const light = ctx.getOn(sunE, 'Light');
      const st = ctx.getOn(sunE, 'Transform');
      if (light) { light.color.set(sky.sun.r, sky.sun.g, sky.sun.b, 1); light.intensity = sky.sunIntensity; }
      if (st) {
        const a = (t - 0.25) * Math.PI * 2;
        const elev = Math.max(0.08, Math.sin(a));
        const dir = ctx.state.dir.set(Math.cos(a) * 0.8, -elev, 0.45).normalize();
        st.setPosition(-dir.x * 200, -dir.y * 200, -dir.z * 200);
        st.updateWorldMatrix();
        st.lookAt(new ctx.math.Vec3(0, 0, 0));
      }
    }
    const ambE = ctx.find('Ambient');
    if (ambE !== undefined) {
      const light = ctx.getOn(ambE, 'Light');
      if (light) { light.color.set(sky.ambient.r, sky.ambient.g, sky.ambient.b, 1); light.intensity = sky.ambientIntensity; }
    }
  },
});

// Builds the archipelago from the world seed with the procgen plugin
// (ctx.engine.procgen), registers generated meshes on the renderer and streams
// islands, decorations, clouds, gate rings and motes in chunks around the
// player. Also animates lanterns, motes, turbine blades and wind streaks.
function pg(ctx) { return ctx.engine.procgen || null; }

const SMALL_PROPS = new Set(['rock', 'crystal', 'stone-lantern', 'lantern', 'windsock', 'column', 'mote']);
function rgba(c) { return { r: c.r, g: c.g, b: c.b, a: 1 }; }

defineScript({
  name: 'WorldStreamer',
  description: 'Generates and streams the procedural archipelago for a seed.',
  props: {
    seed: { type: 'string', default: 'amber-lagoon-42', label: 'World seed' },
    streamRadius: { type: 'number', default: 520, min: 100, max: 2000 },
    lodDistance: { type: 'number', default: 260, min: 50, max: 2000 },
    islands: { type: 'integer', default: 34, min: 4, max: 120 },
    detail: { type: 'boolean', default: true, label: 'Trees, rocks and props' },
  },
  onStart(ctx) {
    const s = ctx.state;
    const P = pg(ctx);
    s.loaded = {}; s.anim = []; s.streaks = []; s.islandLods = []; s.ready = false; s.flocks = [];
    s.tmpQ = new ctx.math.Quat();
    if (!P) {
      ctx.warn('Driftwind needs the procgen plugin (engine.use(procgenPlugin)); the world will be empty.');
      return;
    }
    const seed = P.env.param('seed') || (P.env.param('daily') ? P.seeds.dailySeed() : ctx.props.seed);
    this.build(ctx, seed);
    s.tick = ctx.timer(0.4, () => this.stream(ctx), true);
  },
  onDestroy(ctx) { this.unloadAll(ctx); },

  /** (Re)create the world for a seed: world object, shared registrations, wind streaks. */
  build(ctx, seed) {
    const s = ctx.state, P = pg(ctx);
    this.unloadAll(ctx);
    const W = P.world && P.world.seed === P.seeds.normalizeSeed(seed) ? P.world : P.createWorld(seed, { islands: ctx.props.islands });
    P.world = W;
    s.world = W;
    s.tracker = P.createTracker(W);
    const oldPrefix = s.prefix;
    s.prefix = `${W.seed}:`;
    // Free the previous seed's GPU meshes once every script has re-pointed at the new ones
    // (gliders, ghosts and speed streaks swap their meshes on the same `worldSeed` message).
    if (oldPrefix && oldPrefix !== s.prefix) ctx.timer(1, () => { if (ctx.state.prefix !== oldPrefix) P.unregisterPrefix(oldPrefix); });
    // Wind currents are global: a trail of translucent streaks that flow along each spline.
    const streakDesc = this.reg(ctx, 'wind-streak');
    for (const wind of W.winds) {
      let length = 0;
      for (let i = 1; i < wind.points.length; i++) length += dist(wind.points[i], wind.points[i - 1]);
      const n = Math.max(6, Math.round(length / 3.2));
      for (let k = 0; k < n; k++) {
        const e = this.spawnObject(ctx, 'Wind Streak', streakDesc, wind.points[0], 0, 1, null);
        const off = { x: (hash(k * 7 + wind.id) - 0.5) * wind.radius * 1.4, y: (hash(k * 13 + 3) - 0.5) * wind.radius * 1.2, z: (hash(k * 17 + 5) - 0.5) * wind.radius * 1.4 };
        s.streaks.push({ entity: e, t: ctx.getOn(e, 'Transform'), wind, s: (k / n) * length, length, off, speed: wind.strength * 0.9 });
      }
    }
    this.spawnSea(ctx);
    // Global wind for foliage sway follows the first wind current's heading.
    const r = ctx.engine.renderer;
    if (r && r.wind && W.winds.length) {
      const w0 = W.winds[0].points, a = w0[0], b = w0[Math.min(3, w0.length - 1)];
      const dx = b.x - a.x, dz = b.z - a.z, l = Math.hypot(dx, dz) || 1;
      r.wind.direction.set(dx / l, 0, dz / l);
      r.wind.strength = 1;
    }
    s.ready = true;
    this.stream(ctx);
  },

  /** Register a library key under the world's prefix (idempotent). */
  reg(ctx, key) {
    const P = pg(ctx), s = ctx.state;
    const name = s.prefix + key;
    return P.registered(name) || P.registerGenerated(name, s.world.library(key));
  },

  /**
   * Entity for a generated object. On a vertex-colour renderer the plain lit
   * groups share one merged mesh (`desc.base`) and only emissive, transparent,
   * wind or water groups get their own child; otherwise one child per colour
   * group carries the palette colour. `opts.hideAt` hides the object beyond a
   * distance through `MeshRenderer.lods`; `opts.castShadow` overrides shadows.
   */
  spawnObject(ctx, name, desc, position, yaw, scale, tag, parent, opts) {
    const w = ctx.world, P = pg(ctx), F = P.features;
    const e = w.createEntity(name);
    const t = w.getComponent(e, 'Transform');
    t.setPosition(position.x, position.y, position.z);
    t.setEuler(0, yaw, 0);
    t.setScale(scale, scale, scale);
    if (tag) w.addComponentByType(e, 'Tag', { tags: [tag] });
    if (parent !== undefined) w.setParent(e, parent);
    const parts = F.vertexColors && desc.base ? [desc.base].concat(desc.special) : desc.groups;
    for (const g of parts) {
      const c = w.createEntity(g.name);
      w.setParent(c, e);
      const mr = w.addComponentByType(c, 'MeshRenderer', { mesh: g.mesh });
      P.applyMaterial(mr, g);
      if (opts && opts.castShadow !== undefined && F.shadows) mr.castShadow = opts.castShadow;
      if (opts && opts.hideAt && F.lods) mr.lods = [{ mesh: '', distance: opts.hideAt / Math.max(0.05, scale) }];
      if (g.water && F.water) {
        // Ponds on islands: the stylised water material replaces the flat colour.
        const pal = P.palettes.PALETTES[(opts && opts.biome) || this.biomeOf(ctx, position)];
        mr.castShadow = false;
        w.addComponentByType(c, 'WaterMaterial', {
          deepColor: rgba(P.builder.shade(pal.water, 0.7)), shallowColor: rgba(pal.water), foamColor: rgba(pal.foam),
          waveAmplitude: 0.03, waveLength: 1.6, waveSpeed: 0.5, waveSteepness: 0.1, crestFoam: 0.9, fresnel: 0.35, specular: 0.7, opacity: 0.9, flatShading: true,
        });
      }
    }
    return e;
  },

  biomeOf(ctx, position) {
    const W = ctx.state.world;
    const hit = W && W.nearestIsland(position);
    return hit ? hit.island.biome : (W ? W.primaryBiome : 'meadow');
  },

  /** The sea: a large water plane far below the islands that follows the player (waves are world-space, so moving it is seamless). */
  spawnSea(ctx) {
    const s = ctx.state, P = pg(ctx), W = s.world;
    if (!P.features.water || !P.features.vertexColors) return;
    const name = `${s.prefix}sea`;
    if (!P.registered(name)) {
      const n = 64, size = 7000, pos = [], nrm = [], col = [], idx = [];
      for (let j = 0; j <= n; j++) for (let i = 0; i <= n; i++) {
        pos.push((i / n - 0.5) * size, 0, (j / n - 0.5) * size); nrm.push(0, 1, 0); col.push(0, 0, 0);
      }
      for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) {
        const a = j * (n + 1) + i, b = a + n + 1;
        if ((i + j) % 2 === 0) idx.push(a, b, a + 1, b, b + 1, a + 1); else idx.push(a, b, b + 1, a, b + 1, a + 1);
      }
      const positions = new Float32Array(pos);
      const mesh = { positions, normals: new Float32Array(nrm), colors: new Float32Array(col), indices: new Uint16Array(idx), bounds: P.builder.meshBounds(positions) };
      P.registerGenerated(name, { mesh, groups: [{ name: 'sea', color: { r: 1, g: 1, b: 1 }, data: mesh, triangles: idx.length / 3, water: true }] });
    }
    const pal = P.palettes.PALETTES[W.primaryBiome];
    const e = ctx.world.createEntity('Sea');
    s.seaY = W.bounds.minY - 320;
    const t = ctx.getOn(e, 'Transform');
    t.setPosition(0, s.seaY, 0);
    const mr = ctx.world.addComponentByType(e, 'MeshRenderer', { mesh: name, castShadow: false, frustumCulled: false });
    mr.color.set(1, 1, 1, 1);
    ctx.world.addComponentByType(e, 'WaterMaterial', {
      // crestFoam is a height threshold (0..1): keep it high so only the tallest crests break.
      // Albedo is multiplied by the (orange) golden-hour light, so keep the water bright and saturated to stay teal.
      deepColor: rgba(P.builder.mixRGB(P.builder.rgb('#0e5a86'), pal.water, 0.3)), shallowColor: rgba(P.builder.mixRGB(P.builder.rgb('#35b6d6'), pal.water, 0.35)), foamColor: rgba(pal.foam),
      waveAmplitude: 0.5, waveLength: 30, waveSpeed: 0.45, waveSteepness: 0.15, crestFoam: 0.93, fresnel: 0.35, specular: 0.7, opacity: 1, flatShading: false,
    });
    s.sea = { entity: e, t };
  },

  focus(ctx) {
    for (const e of ctx.findAll('glider')) {
      const pi = ctx.getOn(e, 'PlayerInput');
      if (pi && (pi.owner === 'local' || pi.owner === ctx.net.localId)) return ctx.getOn(e, 'Transform').position;
    }
    const cam = ctx.find('Camera');
    return cam ? ctx.getOn(cam, 'Transform').position : { x: 0, y: 50, z: 0 };
  },

  /** Load/unload chunks around the focus and switch island LODs. */
  stream(ctx) {
    const s = ctx.state;
    if (!s.ready) return;
    const pos = this.focus(ctx);
    const { entered, exited } = s.tracker.update(pos, ctx.props.streamRadius);
    for (const key of exited) this.unloadChunk(ctx, key);
    for (const key of entered) this.loadChunk(ctx, key);
    if (s.sea) s.sea.t.setPosition(Math.round(pos.x / 100) * 100, s.seaY, Math.round(pos.z / 100) * 100);
    const lodD2 = ctx.props.lodDistance * ctx.props.lodDistance;
    for (const isl of s.islandLods) {
      const dx = isl.position.x - pos.x, dz = isl.position.z - pos.z;
      const far = dx * dx + dz * dz > lodD2;
      if (far !== isl.far) {
        isl.far = far;
        for (const mr of isl.hi) mr.visible = !far;
        for (const mr of isl.lo) mr.visible = far;
      }
    }
  },

  loadChunk(ctx, key) {
    const s = ctx.state, W = s.world;
    const content = W.contentOf(key);
    const chunk = { entities: [], anim: [], lods: [], flocks: [] };
    s.loaded[key] = chunk;
    for (const isl of content.islands) this.spawnIsland(ctx, isl, chunk);
    for (const cloud of content.clouds) {
      const e = this.spawnObject(ctx, `Cloud ${cloud.id}`, this.reg(ctx, cloud.key), cloud.position, cloud.yaw, cloud.scale, 'cloud', undefined, { castShadow: false });
      chunk.entities.push(e);
      const rec = { kind: 'drift', t: ctx.getOn(e, 'Transform'), base: cloud.position, speed: cloud.drift, phase: cloud.id };
      chunk.anim.push(rec); s.anim.push(rec);
    }
    for (const ring of content.rings) {
      const desc = this.reg(ctx, 'ring');
      const e = this.spawnObject(ctx, `Gate ${ring.index + 1}`, desc, ring.position, ring.yaw, ring.radius / 6, 'ring');
      ctx.world.addComponentByType(e, 'Script', { script: 'Ring', props: { index: ring.index } });
      chunk.entities.push(e);
    }
  },

  spawnIsland(ctx, spec, chunk) {
    const s = ctx.state, P = pg(ctx), W = s.world;
    const detail = W.islandDetail(spec.id);
    const hiDesc = P.registered(`${s.prefix}island-${spec.id}`) || P.registerGenerated(`${s.prefix}island-${spec.id}`, detail.island);
    const loDesc = P.registered(`${s.prefix}island-${spec.id}-lod`) || P.registerGenerated(`${s.prefix}island-${spec.id}-lod`, detail.lod);
    const root = this.spawnObject(ctx, spec.name, hiDesc, spec.position, 0, 1, 'island', undefined, { biome: spec.biome });
    ctx.world.addComponentByType(root, 'Script', { script: 'Island', props: { id: spec.id, name: spec.name, biome: spec.biome, radius: spec.radius } });
    const hi = [], lo = [];
    for (const c of ctx.world.getChildren(root)) { const mr = ctx.getOn(c, 'MeshRenderer'); if (mr) hi.push(mr); }
    const lodRoot = this.spawnObject(ctx, `${spec.name} (far)`, loDesc, spec.position, 0, 1, null, undefined, { biome: spec.biome });
    for (const c of ctx.world.getChildren(lodRoot)) { const mr = ctx.getOn(c, 'MeshRenderer'); if (mr) { mr.visible = false; lo.push(mr); } }
    const lod = { position: spec.position, hi, lo, far: false };
    chunk.entities.push(root, lodRoot);
    chunk.lods.push(lod); s.islandLods.push(lod);
    if (ctx.props.detail) {
      for (const d of detail.decorations) {
        const small = SMALL_PROPS.has(d.kind);
        const e = this.spawnObject(ctx, d.kind, this.reg(ctx, d.key), d.position, d.yaw, d.scale, null, undefined, { hideAt: small ? 320 : 460, castShadow: small ? false : undefined });
        chunk.entities.push(e);
        if (d.animate && d.animate !== 'sway') {
          const rec = { kind: d.animate, t: ctx.getOn(e, 'Transform'), base: d.position, yaw: d.yaw, phase: d.position.x * 0.37 + d.position.z * 0.11, speed: d.kind === 'turbine-blades' ? 1.6 : 1 };
          chunk.anim.push(rec); s.anim.push(rec);
        }
      }
      const moteDesc = this.reg(ctx, 'mote');
      for (const m of detail.motes) {
        const e = this.spawnObject(ctx, 'Mote', moteDesc, m, 0, 1, 'mote', undefined, { hideAt: 260, castShadow: false });
        chunk.entities.push(e);
        const rec = { kind: 'mote', t: ctx.getOn(e, 'Transform'), base: m, phase: m.x * 0.5 + m.y, speed: 1 };
        chunk.anim.push(rec); s.anim.push(rec);
      }
      if (detail.flock) {
        const fe = ctx.world.createEntity(`Flock ${spec.name}`);
        ctx.getOn(fe, 'Transform').setPosition(detail.flock.center.x, detail.flock.center.y, detail.flock.center.z);
        ctx.world.addComponentByType(fe, 'Script', { script: 'Flock', props: { count: detail.flock.count, radius: detail.flock.radius, meshPrefix: s.prefix } });
        chunk.entities.push(fe);
      }
    }
  },

  unloadChunk(ctx, key) {
    const s = ctx.state;
    const chunk = s.loaded[key];
    if (!chunk) return;
    delete s.loaded[key];
    for (const e of chunk.entities) if (ctx.world.isAlive(e)) ctx.destroy(e);
    if (chunk.anim.length) s.anim = s.anim.filter((a) => !chunk.anim.includes(a));
    if (chunk.lods.length) s.islandLods = s.islandLods.filter((l) => !chunk.lods.includes(l));
  },

  unloadAll(ctx) {
    const s = ctx.state;
    if (s.loaded) for (const key of Object.keys(s.loaded)) this.unloadChunk(ctx, key);
    if (s.streaks) for (const st of s.streaks) if (ctx.world.isAlive(st.entity)) ctx.destroy(st.entity);
    if (s.sea && ctx.world.isAlive(s.sea.entity)) ctx.destroy(s.sea.entity);
    s.sea = null;
    s.loaded = {}; s.anim = []; s.streaks = []; s.islandLods = [];
    if (s.tracker) s.tracker.clear();
  },

  onMessage(ctx, name, data) {
    if (name === 'worldSeed') {
      const P = pg(ctx);
      if (!P) return;
      const seed = P.seeds.normalizeSeed(data.seed);
      if (ctx.state.world && ctx.state.world.seed === seed) return;
      this.build(ctx, seed);
    }
  },

  onUpdate(ctx, dt) {
    const s = ctx.state;
    if (!s.ready) return;
    const time = ctx.time.elapsed;
    for (const a of s.anim) {
      const t = a.t;
      switch (a.kind) {
        case 'bob': t.position.y = a.base.y + Math.sin(time * 0.7 + a.phase) * 0.6; t.markDirty(); break;
        case 'mote': t.position.y = a.base.y + Math.sin(time * 1.6 + a.phase) * 0.35; t.setEuler(0, time * 1.2 + a.phase, 0); break;
        case 'spin': t.rotation.setAxisAngle(UP_AXIS, a.yaw); t.rotation.multiply(s.tmpQ.setAxisAngle(FWD_AXIS, time * a.speed)); t.markDirty(); break;
        case 'drift': t.position.x = a.base.x + Math.sin(time * 0.02 * a.speed + a.phase) * 25; t.markDirty(); break;
      }
    }
    for (const st of s.streaks) {
      st.s += st.speed * dt;
      if (st.s > st.length) st.s -= st.length;
      const p = pointOn(st.wind.points, st.s);
      st.t.setPosition(p.x + st.off.x, p.y + st.off.y, p.z + st.off.z);
      const q = pointOn(st.wind.points, Math.min(st.length, st.s + 2));
      st.t.updateWorldMatrix();
      st.t.lookAt(new ctx.math.Vec3(q.x + st.off.x, q.y + st.off.y, q.z + st.off.z));
    }
  },
});

const UP_AXIS = { x: 0, y: 1, z: 0 };
const FWD_AXIS = { x: 0, y: 0, z: 1 };
function hash(n) { const x = Math.sin(n * 12.9898) * 43758.5453; return x - Math.floor(x); }
function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z); }
function pointOn(points, s) {
  let acc = 0;
  for (let i = 1; i < points.length; i++) {
    const d = dist(points[i], points[i - 1]);
    if (acc + d >= s) { const f = d > 0 ? (s - acc) / d : 0; const a = points[i - 1], b = points[i]; return { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f, z: a.z + (b.z - a.z) * f }; }
    acc += d;
  }
  return points[points.length - 1];
}
